### 2. 사이클 검출 (무방향 그래프)

```cpp
class CycleDetection {
private:
    vector<vector<int>> adj;
    vector<bool> visited;
    int n;

    bool dfs(int v, int parent) {
        visited[v] = true;

        for (int next : adj[v]) {
            if (!visited[next]) {
                if (dfs(next, v)) return true;
            }
            else if (next != parent) {
                return true;  // 사이클 발견
            }
        }
        return false;
    }

public:
    CycleDetection(int vertices) : n(vertices) {
        adj.resize(n);
        visited.resize(n);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    bool hasCycle() {
        fill(visited.begin(), visited.end(), false);

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                if (dfs(i, -1)) return true;
            }
        }
        return false;
    }
};
