### 3. 경로 찾기

```cpp
class PathFinding {
private:
    vector<vector<int>> adj;
    vector<bool> visited;
    vector<int> path;
    int n;

    bool dfs(int current, int target) {
        visited[current] = true;
        path.push_back(current);

        if (current == target) {
            return true;  // 목표 도달
        }

        for (int next : adj[current]) {
            if (!visited[next]) {
                if (dfs(next, target)) {
                    return true;
                }
            }
        }

        path.pop_back();  // 백트래킹
        return false;
    }

public:
    PathFinding(int vertices) : n(vertices) {
        adj.resize(n);
        visited.resize(n);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> findPath(int start, int end) {
        fill(visited.begin(), visited.end(), false);
        path.clear();

        if (dfs(start, end)) {
            return path;
        }
        return {};  // 경로 없음
    }
};
```

