### 1. 위상 정렬 (방향 그래프)

```cpp
class TopologicalSort {
private:
    vector<vector<int>> adj;
    vector<bool> visited;
    stack<int> result;
    int n;

    void dfs(int v) {
        visited[v] = true;

        for (int next : adj[v]) {
            if (!visited[next]) {
                dfs(next);
            }
        }

        result.push(v);  // 완료 시점에 스택에 추가
    }

public:
    TopologicalSort(int vertices) : n(vertices) {
        adj.resize(n);
        visited.resize(n);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);  // 방향 그래프
    }

    vector<int> topologicalSort() {
        fill(visited.begin(), visited.end(), false);

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i);
            }
        }

        vector<int> sorted;
        while (!result.empty()) {
            sorted.push_back(result.top());
            result.pop();
        }

        return sorted;
    }
};
