### 2. 강한 연결 컴포넌트 (SCC)

```cpp
class StronglyConnectedComponents {
private:
    vector<vector<int>> adj, radj;  // 원본 그래프, 역방향 그래프
    vector<bool> visited;
    stack<int> order;
    vector<vector<int>> components;
    int n;

    void dfs1(int v) {
        visited[v] = true;
        for (int next : adj[v]) {
            if (!visited[next]) {
                dfs1(next);
            }
        }
        order.push(v);
    }

    void dfs2(int v, vector<int>& component) {
        visited[v] = true;
        component.push_back(v);

        for (int next : radj[v]) {
            if (!visited[next]) {
                dfs2(next, component);
            }
        }
    }

public:
    StronglyConnectedComponents(int vertices) : n(vertices) {
        adj.resize(n);
        radj.resize(n);
        visited.resize(n);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        radj[v].push_back(u);  // 역방향 엣지
    }

    vector<vector<int>> findSCC() {
        // 1단계: 원본 그래프에서 완료 시간 순서 구하기
        fill(visited.begin(), visited.end(), false);
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs1(i);
            }
        }

        // 2단계: 역방향 그래프에서 SCC 찾기
        fill(visited.begin(), visited.end(), false);
        components.clear();

        while (!order.empty()) {
            int v = order.top();
            order.pop();

            if (!visited[v]) {
                vector<int> component;
                dfs2(v, component);
                components.push_back(component);
            }
        }

        return components;
    }
};
```

