// 스트리밍 환경에서의 KMP
class StreamingKMP {
private:
    string pattern;
    vector<int> failure;
    int currentJ;

public:
    StreamingKMP(const string& pat) : pattern(pat), currentJ(0) {
        // failure 함수 계산
    }

    bool processCharacter(char c) {
        while (currentJ > 0 && c != pattern[currentJ]) {
            currentJ = failure[currentJ - 1];
        }

        if (c == pattern[currentJ]) {
            currentJ++;
        }

        if (currentJ == pattern.length()) {
            currentJ = failure[currentJ - 1];
            return true;  // 매치 발견
        }

        return false;
    }
};
