    cin >> V >> E >> K;

    Dijkstra dijkstra(V + 1);

    for (int i = 0; i < E; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        dijkstra.addEdge(u, v, w);
    }

    vector<int> dist = dijkstra.shortestPath(K);

    for (int i = 1; i <= V; i++) {
